import java.math.BigInteger
import kotlin.math.max
import kotlin.math.min

fun For(a: Int, b: Int, fn: (Int) -> Any?): Any? {
    var res: Any?
    if (a < b) {
        for (i in a..b) {
            res = fn(i)
            if (res != null) return res
        }
    } else {
        for (i in a downTo b) {
            res = fn(i)
            if (res != null) return res
        }
    }
    return null
}

fun <T> Arr(a: Int, b: Int, fn: ((Int, T) -> T)? = null, prev: T = 0 as T): List<T> {
    val p = java.util.concurrent.atomic.AtomicReference(prev)
    if (a < b) {
        return List(b - a + 1) { i ->
            fn?.let { p.set(it(a + i, p.get())) } ?: (a + i) as T
        }
    } else {
        return List(a - b + 1) { i ->
            fn?.let { p.set(it(a - i, p.get())) } ?: (a - i) as T
        }
    }
}

fun <K, V> Map<K, V>.keys(): List<K> = this.keys.toList()
fun <K, V> Map<K, V>.values(): List<V> = this.values.toList()
fun <K, V> Map<K, V>.entries(): List<Pair<K, V>> = this.entries.toList()

fun <T> Iterable<T>.sum(fn: (T) -> Number = { it as Number }): Double = this.map { fn(it).toDouble() }.sum()

fun <T> Iterable<T>.uniq(fn: (T) -> Any? = { it }): List<T> {
    val set = mutableSetOf<Any>()
    return this.filter { val v = fn(it); v !in set && set.add(v) }
}

fun <T> Iterable<T>.toObj(fn: (T) -> Pair<Any, Any>): Map<Any, Any> {
    return this.map(fn).toMap()
}

fun <T> List<T>.min(fn: ((T, Int) -> Number)? = null): Triple<T, Int, Number> {
    var minVal: Number = Double.POSITIVE_INFINITY
    var minIdx = -1
    var minElem: T? = null
    this.forEachIndexed { i, v ->
        val val = fn?.invoke(v, i) ?: (v as Number)
        if (val.toDouble() < minVal.toDouble()) {
            minVal = val
            minIdx = i
            minElem = v
        }
    }
    return Triple(minElem!!, minIdx, minVal)
}

fun <T> List<T>.max(fn: ((T, Int) -> Number)? = null): Triple<T, Int, Number> {
    var maxVal: Number = Double.NEGATIVE_INFINITY
    var maxIdx = -1
    var maxElem: T? = null
    this.forEachIndexed { i, v ->
        val val = fn?.invoke(v, i) ?: (v as Number)
        if (val.toDouble() > maxVal.toDouble()) {
            maxVal = val
            maxIdx = i
            maxElem = v
        }
    }
    return Triple(maxElem!!, maxIdx, maxVal)
}

fun gcd(a: Long, b: Long): Long = if (b == 0L) a else gcd(b, a % b)

fun mod(a: BigInteger, n: BigInteger, m: BigInteger): BigInteger {
    if (n == BigInteger.ZERO) return BigInteger.ONE
    if (n % BigInteger.TWO == BigInteger.ZERO) return mod((a * a) % m, n / BigInteger.TWO, m)
    return (a * mod(a, n - BigInteger.ONE, m)) % m
}

fun extendedEuclid(a: Long, b: Long): Pair<Long, Long> {
    if (b == 0L) return 1L to 0L
    val (x, y) = extendedEuclid(b, a % b)
    return y to (x - (a / b) * y)
}

fun main() {
    val input = System.stdin.readText().trim()
    val inp = input.split("\\s+".toRegex()).filter { it.isNotEmpty() }
    var r = 0

    val n = inp[0].toInt()
    val k = inp[1].toInt()
    val s = inp[2]
    val t = inp[3]

    if (t[0] == t[1]) {
        val x = min(s.count { it == t[0] } + k, n)
        println(x * (x - 1) / 2)
        return
    }

    // f[i][j][cnt0] = max score
    // Dimensions: (n+1) x (k+1) x (n+1)
