import java.math.BigInteger

fun main() {
    val input = System.stdin.readText().trim()
    val inp = input.split("\\s+".toRegex()).filter { it.isNotEmpty() }
    val n = inp[0].toInt()
    val k = inp[1].toInt()
    val s = inp[2]
    val t = inp[3]

    if (t[0] == t[1]) {
        val count = s.count { it == t[0] }
        val x = Math.min(count + k, n)
        println(x * (x - 1) / 2)
        return
    }

    val INF = -1_000_000_000
    val f = Array(n + 1) { Array(k + 1) { IntArray(n + 1) { INF } } }
    f[0][0][0] = 0

    for (i in 0 until n) {
        for (j in 0..k) {
            for (cnt0 in 0..i) {
                val cur = f[i][j][cnt0]
                if (cur == INF) continue

                val e0 = if (s[i] == t[0]) 1 else 0
                val e1 = if (s[i] == t[1]) 1 else 0

                // Keep current character
                val nCnt0 = cnt0 + e0
                f[i + 1][j][nCnt0] = Math.max(f[i + 1][j][nCnt0], cur + e1 * cnt0)

                // Change to t[0]
                if (j < k) {
                    f[i + 1][j + 1][cnt0 + 1] = Math.max(f[i + 1][j + 1][cnt0 + 1], cur)
                }

                // Change to t[1]
                if (j < k) {
                    f[i + 1][j + 1][cnt0] = Math.max(f[i + 1][j + 1][cnt0], cur + cnt0)
                }
            }
        }
    }

    var ans = 0
    for (j in 0..k) {
        for (cnt0 in 0..n) {
            ans = Math.max(ans, f[n][j][cnt0])
        }
    }
    println(ans)
}

